def is_raising(body):
    """Return true if the given statement node raises an exception"""
    if isinstance(body, ast.Raise):
        return True
    elif isinstance(body, ast.Try):
        for handler in body.handlers:
            if isinstance(handler, ast.ExceptHandler):
                if handler.type is None:
                    return True
                elif isinstance(handler.type, ast.Tuple):
                    for exc_type in handler.type.elts:
                        if isinstance(exc_type, ast.Name):
                            return True
                elif isinstance(handler.type, ast.Name):
                    return True
        return False
    elif isinstance(body, ast.FunctionDef):
        for stmt in body.body:
            if is_raising(stmt):
                return True
    elif isinstance(body, ast.If):
        if is_raising(body.test) or is_raising(body.body) or is_raising(body.orelse):
            return True
    elif isinstance(body, ast.For):
        if is_raising(body.body) or is_raising(body.orelse):
            return True
    elif isinstance(body, ast.While):
        if is_raising(body.body) or is_raising(body.orelse):
            return True
    elif isinstance(body, ast.With):
        for item in body.items:
            if is_raising(item.context_expr):
                return True
        if is_raising(body.body):
            return True
    elif isinstance(body, ast.Expr):
        if isinstance(body.value, ast.Call):
            return True
    return False

