def matchmaker_request(url, token, method, content_type=None, accept=None, data=None):
    import requests
    headers = {'Authorization': f'Bearer {token}', 'Content-Type': content_type if content_type else 'application/json', 'Accept': accept if accept else 'application/json'}
    if method == 'GET':
        response = requests.get(url, headers=headers)
    elif method == 'POST':
        response = requests.post(url, headers=headers, json=data)
    elif method == 'DELETE':
        response = requests.delete(url, headers=headers)
    else:
        raise ValueError('Unsupported method')
    if response.status_code == 200:
        return response.json()
    else:
        response.raise_for_status()

def read_logfile(log_file):
    import re
    import os
    runargs = {}
    paths = {}
    with open(log_file, 'r') as file:
        lines = file.readlines()
    for line in lines:
        if 'Data directory:' in line:
            paths['data_dir'] = line.split(': ')[1].strip()
        elif 'SRM database:' in line:
            paths['srm_db'] = line.split(': ')[1].strip()
    function_pattern = re.compile('Function: (\\w+)')
    args_pattern = re.compile('Args: \\((.*?)\\)')
    kwargs_pattern = re.compile('Kwargs: \\{(.*?)\\}')
    for line in lines:
        function_match = function_pattern.search(line)
        if function_match:
            function_name = function_match.group(1)
            args_match = args_pattern.search(line)
            kwargs_match = kwargs_pattern.search(line)
            args = tuple(eval(args_match.group(1))) if args_match else ()
            kwargs = eval(f'{{{kwargs_match.group(1)}}}') if kwargs_match else {}
            runargs[function_name] = {'args': args, 'kwargs': kwargs}
    return (runargs, paths)

