def random_expr(depth, vlist, ops):
    if depth == 0:
        return ExprNode(random.choice(vlist))
    else:
        op = random.choice(ops)
        left = random_expr(depth - 1, vlist, ops)
        right = random_expr(depth - 1, vlist, ops)
        return ExprNode(op, left, right)

class ExprNode:
    """A node in an expression tree.

  Attributes:
    op: An ExprOp instance or None if this is a leaf node.
    left: An ExprNode instance or None if this is a leaf node.
    right: An ExprNode instance or None if this is a leaf node.
    value: A char or None if this is an internal node."""

    def __init__(self, op=None, left=None, right=None, value=None):
        self.op = op
        self.left = left
        self.right = right
        self.value = value

    def __str__(self):
        if self.op is None:
            return str(self.value)
        else:
            return f'({self.left} {self.op} {self.right})'

class ExprOp:
    """An operator in an expression tree.

  Attributes:
    symbol: A string representing the operator symbol.
    precedence: An integer representing the operator precedence."""

    def __init__(self, symbol, precedence):
        self.symbol = symbol
        self.precedence = precedence

    def __str__(self):
        return self.symbol

