def addCatalogEntry(root, catalogPath):
    """Add a CATALOG entry to the root of the SGML super catalog."""
    catalogEntry = ET.Element('CATALOG')
    catalogEntry.text = catalogPath
    root.append(catalogEntry)

def removeCatalogEntry(root, catalogPath):
    """Remove a CATALOG entry from the SGML super catalog."""
    for catalogEntry in root.findall('CATALOG'):
        if catalogEntry.text == catalogPath:
            root.remove(catalogEntry)

def saveSGMLSuperCatalog(root, filename):
    """Save the modified SGML super catalog to a file."""
    tree = ET.ElementTree(root)
    tree.write(filename)

