def read_pal_version():
    import re
    with open('configure.ac', 'r') as file:
        content = file.read()
        match = re.search('AC_INIT\\(\\[PAL\\], \\[(\\d+)\\.(\\d+)\\.(\\d+)\\]\\)', content)
        if match:
            vers = match.group(0)
            maj = int(match.group(1))
            min = int(match.group(2))
            patchlevel = int(match.group(3))
            return (vers, maj, min, patchlevel)
        else:
            raise ValueError('Version number not found in configure.ac')

