def save_key(key, filename, password=None, use_openssh=False):
    """Save a private RSA key to a file.

        @param key: the private key to save.
        @type key: L{RSAKey}
        @param filename: the filename to save the key to.
        @type filename: str
        @param password: an optional password to encrypt the key file.
        @type password: str
        @param use_openssh: if True, save the key in OpenSSH format.
        @type use_openssh: bool"""
    from Crypto.IO import PEM
    if use_openssh:
        from Crypto.IO import OpenSSH
        key_data = OpenSSH.encode_private(key)
    else:
        key_data = PEM.encode(key, password=password)
    with open(filename, 'wb') as f:
        f.write(key_data)

def load_key(filename, password=None):
    """Load a private RSA key from a file.

        @param filename: the filename to load the key from.
        @type filename: str
        @param password: an optional password to decrypt the key file.
        @type password: str
        @return: the loaded private key
        @rtype: L{RSAKey}"""
    from Crypto.IO import PEM
    with open(filename, 'rb') as f:
        key_data = f.read()
    key = PEM.decode(key_data, password=password)
    return key

