def epcr_primers(self, primerfile):
    with open(primerfile, 'r') as file:
        lines = file.readlines()
    for line in lines:
        line = line.strip()
        if line and (not line.startswith('#')):
            (primer_name, primer_sequence) = line.split('\t')
            expanded_sequences = self.expand_degenerate_bases(primer_sequence)
            with open('output_primers.txt', 'a') as output_file:
                for seq in expanded_sequences:
                    output_file.write(f'{primer_name}\t{seq}\n')

    def expand_degenerate_bases(self, sequence):
        """Expand degenerate bases in a DNA sequence"""
        degenerate_bases = {'R': ['A', 'G'], 'Y': ['C', 'T'], 'S': ['G', 'C'], 'W': ['A', 'T'], 'K': ['G', 'T'], 'M': ['A', 'C'], 'B': ['C', 'G', 'T'], 'D': ['A', 'G', 'T'], 'H': ['A', 'C', 'T'], 'V': ['A', 'C', 'G'], 'N': ['A', 'C', 'G', 'T']}
        if not sequence:
            return []

        def expand(seq, index):
            if index == len(seq):
                return ['']
            expanded = []
            for base in degenerate_bases.get(seq[index], [seq[index]]):
                for suffix in expand(seq, index + 1):
                    expanded.append(base + suffix)
            return expanded
        return expand(sequence, 0)

