    """Handle the error based on the exception type."""
    if isinstance(exp, ConnectionError):
        self._retry_request(request)
    elif isinstance(exp, TimeoutError):
        self._retry_request(request)
    elif isinstance(exp, HTTPError):
        self._handle_http_error(request, exp)
    else:
