def elog(exc, func, args=None, kwargs=None, str=str, pretty=True, name=''):
    if args is None:
        args = ()
    if kwargs is None:
        kwargs = {}
    if pretty:
        args_str = ', '.join([str(arg) for arg in args])
        kwargs_str = ', '.join([f'{key}={str(value)}' for (key, value) in kwargs.items()])
        func_str = f"{name}{func.__name__}({args_str}{(', ' if args and kwargs else '')}{kwargs_str})"
    else:
        func_str = f'{name}{func.__name__}({args}, {kwargs})'
    try:
        result = func(*args, **kwargs)
    except Exception as e:
        print(f'Exception in {func_str}: {e}')
        return None
    else:
        return result

