def find_modules_with_decorators(path, decorator_module, decorator_name):
    import os
    import ast
    import importlib.util

    def is_decorated_with(node, decorator_module, decorator_name):
        for decorator in node.decorator_list:
            if isinstance(decorator, ast.Call):
                decorator = decorator.func
            if isinstance(decorator, ast.Attribute):
                if decorator.attr == decorator_name and decorator.value.id == decorator_module:
                    return True
            elif isinstance(decorator, ast.Name):
                if decorator.id == decorator_name:
                    return True
        return False

    def scan_file(file_path):
        with open(file_path, 'r', encoding='utf-8') as file:
            tree = ast.parse(file.read(), filename=file_path)
            for node in ast.walk(tree):
                if isinstance(node, (ast.FunctionDef, ast.ClassDef)) and is_decorated_with(node, decorator_module, decorator_name):
                    print(f'Found {decorator_name} in {file_path} at {node.name}')

    def scan_directory(directory):
        for (root, _, files) in os.walk(directory):
            for file in files:
                if file.endswith('.py'):
                    scan_file(os.path.join(root, file))
    if os.path.isfile(path):
        scan_file(path)
    elif os.path.isdir(path):
        scan_directory(path)
    else:
        print('Invalid path provided.')

def hash(value, arg):
    import hashlib
    if arg == 'md5':
        return hashlib.md5(value.encode()).hexdigest()
    elif arg == 'sha1':
        return hashlib.sha1(value.encode()).hexdigest()
    elif arg == 'sha256':
        return hashlib.sha256(value.encode()).hexdigest()
    elif arg == 'sha512':
        return hashlib.sha512(value.encode()).hexdigest()
    else:
        raise ValueError('Unsupported hash algorithm')

