def _read_file(self, path):
    """Read the contents of a file."""
    try:
        with open(path, 'r') as file:
            return {'content': file.read()}
    except PermissionError:
        raise PermissionError(f"Permission denied: '{path}'")
    except UnicodeDecodeError:
        return {'content': 'Binary file content'}

def version():
    import subprocess
    import re
    from graphviz import ExecutableNotFound
    try:
        output = subprocess.check_output(['dot', '-V'], stderr=subprocess.STDOUT)
    except FileNotFoundError:
        raise ExecutableNotFound('Graphviz executable not found')
    except subprocess.CalledProcessError as e:
        raise e
    match = re.search('version (\\d+\\.\\d+(\\.\\d+)?)', output.decode('utf-8'))
    if match:
        version_str = match.group(1)
        return tuple(map(int, version_str.split('.')))
    else:
        raise RuntimeError('Could not parse version number from output')

def exec_stmt_handle(self, tokens):
    if tokens[0] in ('exec', 'exec_stmt'):
        if len(tokens) == 2:
            code = tokens[1]
            exec(code)
        elif len(tokens) == 4:
            code = tokens[1]
            globals_dict = tokens[2]
            locals_dict = tokens[3]
            exec(code, globals_dict, locals_dict)
        else:
            raise ValueError('Invalid exec statement format')
    else:
        raise ValueError('Invalid statement type')

