def frombed(args):
    parser = optparse.OptionParser()
    parser.add_option('-v', '--verbose', action='store_true', dest='verbose', default=False, help='make lots of noise [default]')
    parser.add_option('-o', '--output', dest='output', default='output.fasta', help='output file name [default: %default]')
    (options, args) = parser.parse_args(args)
    if len(args) != 3:
        parser.error('incorrect number of arguments')
    (bedfile, contigfasta, readfasta) = args
    contigs = SeqIO.to_dict(SeqIO.parse(contigfasta, 'fasta'))
    reads = SeqIO.to_dict(SeqIO.parse(readfasta, 'fasta'))
    with open(bedfile, 'r') as f:
        for line in f:
            fields = line.strip().split('\t')
            if len(fields) < 4:
                continue
            (contig_id, start, end, read_id) = fields[:4]
            (start, end) = (int(start), int(end))
            if contig_id not in contigs:
                if options.verbose:
                    print(f'Warning: Contig {contig_id} not found in contigfasta.')
                continue
            if read_id not in reads:
                if options.verbose:
                    print(f'Warning: Read {read_id} not found in readfasta.')
                continue
            read_seq = reads[read_id].seq
            contig_seq = contigs[contig_id].seq
            if start < 0 or end > len(contig_seq):
                if options.verbose:
                    print(f'Warning: Read {read_id} placement out of bounds for contig {contig_id}.')
                continue
            new_seq = contig_seq[:start] + read_seq

