def distance_measure_common(A, func, alpha, R, k, epsilon):
    import numpy as np
    n = A.shape[0]
    W = np.zeros((n, n))
    for i in range(n):
        for j in range(n):
            if i != j:
                relaxation_vector = A[i] - A[j]
                strength = func(relaxation_vector, alpha, R, k, epsilon)
                W[i, j] = strength
    return W

def func_example(relaxation_vector, alpha, R, k, epsilon):
    """Example function to calculate strength of connection."""
    import numpy as np
    norm = np.linalg.norm(relaxation_vector)
    if norm < epsilon:
        return 0
    else:
        return np.exp(-alpha * (norm / R) ** k)
