def _tabulate(self, info_dict, col_widths, changed, order, bounds_dict):
    table = [self._format_row(order, col_widths, bounds_dict)]
    for param in info_dict:
        row = self._format_row(order, col_widths, info_dict[param])
        if param in changed:
            row = self._highlight_row(row)
        table.append(row)
    return table

def _format_row(self, order, col_widths, data_dict):
    """Formats a row of the table based on the order and column widths."""
    row = []
    for col in order:
        value = data_dict.get(col, '')
        formatted_value = self._pad_value(value, col_widths[col])
        row.append(formatted_value)
    return ' | '.join(row)

def _pad_value(self, value, width):
