def _create_and_send_json_bulk(self, payload, req_url, request_type='POST'):
    import requests
    import json
    if request_type not in ['POST', 'DELETE']:
        raise CraftAiBadRequestError("Invalid request type. Must be 'POST' or 'DELETE'.")
    try:
        json_payload = json.dumps(payload)
    except (TypeError, ValueError) as e:
        raise CraftAiBadRequestError(f'Invalid payload format: {e}')
    headers = {'Content-Type': 'application/json'}
    if request_type == 'POST':
        response = requests.post(req_url, data=json_payload, headers=headers)
    elif request_type == 'DELETE':
        response = requests.delete(req_url, data=json_payload, headers=headers)
    if response.status_code not in [200, 201, 204]:
        raise CraftAiBadRequestError(f'Request failed with status code {response.status_code}: {response.text}')
    try:
        response_data = response.json()
    except ValueError:
        raise CraftAiBadRequestError('Failed to parse response as JSON.')
    return response_data

