    except ValueError as e:
        raise ValueError(f'Invalid JSON: {e}')
    if not isinstance(data, dict):
        raise TypeError('JSON data must be a dictionary')
    if hasattr(cls, '_fromJSON'):
        return cls._fromJSON(data)
    else:
        return cls(**data)

