def rna_transcript_expression_dict_from_cufflinks(file_path):
    """Parses a Cufflinks tracking file and returns a dictionary mapping
    Ensembl transcript IDs to FPKM expression values."""
    expression_dict = {}
    with open(file_path, 'r') as file:
        for line in file:
            if line.startswith('#'):
                continue
            fields = line.strip().split('\t')
            transcript_id = fields[9]
            fpkm = float(fields[10])
            expression_dict[transcript_id] = fpkm
    return expression_dict

def rna_transcript_expression_dict_from_stringtie(file_path):
    """Parses a StringTie GTF file and returns a dictionary mapping
    Ensembl transcript IDs to FPKM expression values."""
    expression_dict = {}
    with open(file_path, 'r') as file:
        for line in file:
            if line.startswith('#'):
                continue
            fields = line.strip().split('\t')
            if fields[2] == 'transcript':
                attributes = fields[8]
                transcript_id = attributes.split('transcript_id "')[1].split('"')[0]
                fpkm = float(attributes.split('FPKM "')[1].split('"')[0])
                expression_dict[transcript_id] = fpkm
    return expression_dict

