    if os.path.exists('/sys/class/dmi/id'):
        with open('/sys/class/dmi/id/sys_vendor', 'r') as f:
            manufacturer = f.read().strip()
        with open('/sys/class/dmi/id/product_name', 'r') as f:
            model = f.read().strip()
    else:
        try:
            output = subprocess.check_output(['dmidecode', '-t', 'system'], text=True)
            lines = output.split('\n')
            manufacturer = next((line.split(': ')[1] for line in lines if 'Manufacturer' in line)).strip()
            model = next((line.split(': ')[1] for line in lines if 'Product Name' in line)).strip()
        except subprocess.CalledProcessError:
            return 'Error: dmidecode command failed'
        except FileNotFoundError:
            return 'Error: dmidecode command not found'
    return f'Manufacturer: {manufacturer}, Model: {model}'

def get_rev_options(url, rev):
    import subprocess
    import os
    import re
    if not re.match('^https?://', url):
        raise ValueError('Invalid SVN URL')
    if not re.match('^\\d+$', rev):
        raise ValueError('Invalid SVN revision number')
    try:
        result = subprocess.run(['svn', 'info', '--show-item', 'revision', url], capture_output=True, text=True, check=True)
        current_rev = result.stdout.strip()
        if current_rev != rev:
            raise ValueError(f'Requested revision {rev} does not match the current revision {current_rev}')
        return {'revision': current_rev}
    except subprocess.CalledProcessError as e:
        raise ValueError(f'Error retrieving SVN revision: {e.stderr}')
