    import requests
    from io import StringIO
    response = requests.get(url)
    response.raise_for_status()
    file_type = kwargs.get('file_type', None)
    delimiter = kwargs.get('delimiter', None)
    if file_type == 'csv':
        df = pd.read_csv(StringIO(response.text), delimiter=delimiter, header=None)
    elif file_type == 'tsv':
        df = pd.read_csv(StringIO(response.text), delimiter='\t', header=None)
    else:
        df = pd.read_csv(StringIO(response.text), delimiter=delimiter, header=None)
    headers = kwargs.get('headers', None)
    if headers is not None:
        if isinstance(headers, int):
            df.columns = df.iloc[headers]
            df = df.drop(headers)
        elif isinstance(headers, list):
            df.columns = headers
    result_dict = dict(zip(df.iloc[:, 0], df.iloc[:, 1]))
    return result_dict

