def checkSimbad(g, target, maxobj=5, timeout=5):
    import requests
    from astropy.coordinates import SkyCoord
    from astropy import units as u
    import time
    try:
        target_coord = SkyCoord(target, frame='icrs')
    except ValueError:
        raise ValueError('Invalid target format. Please provide a valid ICRS coordinate.')
    url = 'http://simbad.u-strasbg.fr/simbad/sim-id'
    params = {'Ident': target_coord.to_string('hmsdms'), 'output.format': 'votable', 'output.max': maxobj, 'output.params': 'main_id,coordinates,otypes'}
    start_time = time.time()
    try:
        response = requests.get(url, params=params, timeout=timeout)
        response.raise_for_status()
    except requests.exceptions.Timeout:
        raise TimeoutError('The request to Simbad timed out.')
    except requests.exceptions.HTTPError as e:
        raise Exception(f'HTTP error occurred: {e}')
    except requests.exceptions.RequestException as e:
        raise Exception(f'An error occurred: {e}')
    from astropy.io.votable import parse_single_table
    try:
        table = parse_single_table(response.content)
        data = table.array
    except Exception as e:
        raise Exception(f'Failed to parse the response from Simbad: {e}')
    results = []
    for row in data:
        main_id = row['MAIN_ID']
        coordinates = row['COORD']
        otypes = row['OTYPE']
        results.append({'main_id': main_id, 'coordinates': coordinates, 'otypes': otypes})
    return results

def _find_conda_env_paths_from_conda(mgr):
    import subprocess
    import json
    try:
        result = subprocess.run(['conda', 'env', 'list', '--json'], capture_output=True, text=True, check=True)
        envs_info = json.loads(result.stdout)
        env_paths = [env['prefix'] for env in envs_info['envs']]
        return env_paths
    except (subprocess.CalledProcessError, json.JSONDecodeError):
        return []

def render_template(request, app, template_name, context=None, subdir='templates', def_name=None):
    if context is None:
        context = {}
    if def_name is not None:
        context['def_name'] = def_name
    template_path = os.path.join(app.config[subdir], template_name)
    with open(template_path, 'r') as file:
        template_content = file.read()
    rendered_content = render_string(template_content, context)
    return rendered_content

def render_string(template_string, context):
    """Renders a template string with the given context."""
    template = Template(template_string)
    return template.render(context)

class Template:

    def __init__(self, template_string):
        self.template_string = template_string

    def render(self, context):
        """Renders the template with the given context."""
        for (key, value) in context.items():
            self.template_string = self.template_string.replace('{{' + key + '}}', str(value))
        return self.template_string

