def content(self, **args):
    gistName = args.get('gistName')
    gistID = args.get('gistID')
    if gistID:
        return self.fetch_gist_content_by_id(gistID)
    elif gistName:
        return self.fetch_gist_content_by_name(gistName)
    else:
        raise ValueError('Either gistName or gistID must be provided')

def fetch_gist_content_by_id(self, gistID):
    """Fetches the content of a gist by its ID"""
    response = requests.get(f'https://api.github.com/gists/{gistID}')
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f'Failed to fetch gist content by ID: {gistID}')

def fetch_gist_content_by_name(self, gistName):
    """Fetches the content of a gist by its name"""
    response = requests.get('https://api.github.com/gists')
    if response.status_code == 200:
        gists = response.json()
        for gist in gists:
            if gistName in gist['files']:
                return self.fetch_gist_content_by_id(gist['id'])
        raise Exception(f'No gist found with name: {gistName}')
    else:
        raise Exception('Failed to fetch gists')

