def plot(self, pcs=[1, 2], ax=None, cmap=None, cdict=None, legend=True, title=None, outfile=None):
    pca = PCA(n_components=max(pcs))
    X_pca = pca.fit_transform(self.data)
    if ax is None:
        (fig, ax) = plt.subplots()
    if cdict is not None:
        colors = [cdict[pop] for pop in self.populations]
    elif cmap is not None:
        colors = cmap(np.linspace(0, 1, len(self.populations)))
    else:
        colors = plt.cm.tab10(np.linspace(0, 1, len(self.populations)))
    for (i, pop) in enumerate(self.populations):
        idx = np.where(self.populations == pop)[0]
        ax.scatter(X_pca[idx, pcs[0] - 1], X_pca[idx, pcs[1] - 1], c=colors[i], label=pop)
    if legend:
        ax.legend()
    if title:
        ax.set_title(title)
    if outfile:
        plt.savefig(outfile)
    plt.show()

