def integral(A=None, dF=None, F=None, axis=0, trapez=False, cumulative=False):
    if A is None:
        A = np.ones(len(dF) + 1)
    if dF is None and F is None:
        dF = np.ones(len(A) - 1)
    elif F is not None:
        dF = np.diff(F)
    if trapez:
        A = (A[:-1] + A[1:]) / 2
    if cumulative:
        return np.cumsum(np.concatenate(([0], dF * A[:-1])))
    else:
        return np.concatenate(([0], dF * A[:-1]))
